        await ctx.api.saves.rollSave(card, tiedT.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, tiedT.id, {action: 'degree', degree: 'failure'});
        let refused = false; try { await ctx.api.saves.finalize(card); } catch (error) { refused = true; }
        await ctx.api.saves.correctTarget(card, tiedT.id, {action: 'attribute-condition', degree: 'drained'});
        await ctx.api.saves.finalize(card); await wait(1500);
        const conds = actor => ['enfeebled', 'clumsy', 'drained', 'stupefied'].map(slug => [slug, actor.getCondition(slug)?.value ?? 0]).filter(([, v]) => v).map(([slug, v]) => `${slug} ${v}`);
        const applied = {strong: conds(strong), tied: conds(tied)};
