            await ctx.api.saves.rollSave(c, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(c, t.id, {action: 'degree', degree: t.actorUuid === strong.uuid ? 'success' : 'failure'});
            await ctx.api.saves.finalize(c); await wait(1200);
