            const fixture = await ctx.setup('Mirror Malefactors');
            const victim = await ctx.actor('mirror target', {level: 5}); await victim.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tVictim = await place(victim, 25 * g, 1 * g); await wait(500);
