            const sharp = await ctx.actor('visions sharp'), dull = await ctx.actor('visions dull'); actors.push(sharp, dull);
            await sharp.update({'system.perception.mod': 60, 'system.attributes.hp.max': 400, 'system.attributes.hp.value': 400});
            await dull.update({'system.perception.mod': -30, 'system.attributes.hp.max': 400, 'system.attributes.hp.value': 400});
