            const g = canvas.grid.size;
            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const casterToken = canvas.scene.tokens.find(t => t.actorId === s.caster.id); await casterToken.update({x: 20 * g, y: 10 * g}, {animate: false});
            await s.caster.update({'system.attributes.hp.max': 300, 'system.attributes.hp.value': 300});
            const near = await ctx.actor('ignition near'), far = await ctx.actor('ignition far'); actors.push(near, far);
            for (const a of [near, far]) await a.update({'system.attributes.hp.max': 300, 'system.attributes.hp.value': 300});
