        for (const actor of actors) { await canvas.scene.deleteEmbeddedDocuments('Token', canvas.scene.tokens.filter(t => t.actorId === actor.id).map(t => t.id)); await actor.delete(); }
        const c = out.cast ?? {}, tn = out.turns ?? {};
        assert(!out.error && c.kind === 'aura-turn-effect' && c.effect && c.quickened && tn.near >= 1 && tn.near <= 12 && tn.far === 0 && tn.caster === 0, `Rank 9 batch 3: ${JSON.stringify(out)}`);
