                const fCard = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId), ft = ctx.state(fCard).targets[0];
                await ctx.api.saves.rollSave(fCard, ft.id, {skipDialog: true}); await ctx.api.saves.correctTarget(fCard, ft.id, {action: 'degree', degree: 'failure'}); await ctx.api.saves.finalize(fCard); await wait(1200);
