            const run = async (name, degree, extra = {}) => { const ritual = await ctx.setup(name); const plan = await ctx.api.compile(ritual.spell);
                return {ritual, result: await ctx.api.execute(ritual.spell, {sourceActor: ritual.caster, plan, skipConfirmation: true, degree, secondaryCasters: [helper.uuid], ...extra})}; };
