            const foe = await ctx.actor('vapor foe'); await foe.update({'system.attributes.hp.max': 400}); await foe.update({'system.attributes.hp.value': 400});
            const tFoe = await place(foe, 19 * g, 12 * g); await wait(800);
            const plan = await ctx.api.compile(fixture.spell);
