        assert(!out.error && out.terrain && f.lost >= 6 && f.lost <= 36 && JSON.stringify(f.persistent) === '["3d6 bleed"]' && f.speedDrop === 10 && JSON.stringify(f.note) === '["unlimited"]'
            && c.lost >= 12 && c.lost <= 72 && c.persistent?.length === 1 && /3d6/.test(c.persistent[0]) && c.speedDrop === 15, `Rank 5 batch 47: ${JSON.stringify(out)}`);
        return {batch47: out};
