    // Rank 5 batch 46: Slither at 7th (caster level 13) — two creatures in the burst at the cast: a failure (3d6 piercing, persistent 2d6 poison, Grabbed
    // until it Escapes) and a critical failure (double, persistent 2×2d6, Restrained); the grabbed one's Escape is graded against the spell DC.
    async rank5Batch46(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
        const g = canvas.grid.size;
        const out = {};
        let region = null;
        try {
            const fixture = await ctx.setup('Slither');
            await fixture.caster.update({'system.details.level.value': 13}); await fixture.spell.update({'system.location.heightenedLevel': 7});
            const fresh = async name => { const a = await ctx.actor(name); await a.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300}); return a; };
            const grabbed = await fresh('slither failure'), held = await fresh('slither critical failure');
            await place(grabbed, 26 * g, 1 * g); await place(held, 27 * g, 2 * g); await wait(600);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Slither', shapes: [{type: 'circle', x: 27 * g, y: 2 * g, radius: 2.5 * g}], color: '#335533'}]);
            const plan = await ctx.api.compile(fixture.spell);
            const started = await ctx.api.ongoing.startLingering(fixture.spell, plan, {castRank: 7, region, dc: 30});
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            await wait(800);
            out.results = {};
            for (const [actor, degree] of [[grabbed, 'failure'], [held, 'criticalFailure']]) {
                const o = rec().obligations.find(x => x.kind === 'membership' && x.status === 'pending' && x.actorUuid === actor.uuid);
                if (!o) { out.results[degree] = 'not exposed'; continue; }
                await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: o.key, affected: true}); await wait(800);
                const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId);
                const t = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1500);
                const st = ctx.state(card);
                out.results[degree] = {lost: 300 - actor.hitPoints.value, formulas: (st.targets[0].damage?.formulas ?? st.damage?.formulas ?? null),
                    persistent: actor.itemTypes.condition.filter(c => c.slug === 'persistent-damage').map(c => `${c.system.persistent?.formula} ${c.system.persistent?.damageType}`),
                    grabbed: actor.hasCondition('grabbed'), restrained: actor.hasCondition('restrained')};
            }
            const {gradeEscapeCandidates} = await import(`/modules/pf2e-automatic-resolution/scripts/escape-termination.js?v=${Date.now()}`);
            out.escape = gradeEscapeCandidates(grabbed.items, {total: 40, natural: 10}).filter(x => x.escaped).map(x => x.escape.dc);
            await ctx.api.ongoing.request('end', {castId: started.castId}); await wait(800);
        } catch (error) { out.error = error.stack ?? error.message; }
        if (region && canvas.scene.regions.get(region.id)) await region.delete();
        const f = out.results?.failure ?? {}, c = out.results?.criticalFailure ?? {};
        assert(!out.error && f.lost >= 3 && f.lost <= 18 && JSON.stringify(f.persistent) === '["2d6 poison"]' && f.grabbed && !f.restrained
            && c.lost >= 6 && c.lost <= 36 && c.lost % 2 === 0 && c.persistent?.length === 1 && /2d6|\(2\*/.test(c.persistent[0]) && c.restrained
            && JSON.stringify(out.escape) === '[30]', `Rank 5 batch 46: ${JSON.stringify(out)}`);
        return {batch46: out};
    },
    // Rank 3 batch 69: Mind Reading — a success (Intelligence +5 against the caster's): "higher" whispered; a failure (−3): "lower" and the thoughts
    // note; a critical failure: the note for the sustained minute; a critical success: nothing; all immune to this caster (a second cast refuses them).
