    // Rank 4 batch 75: Trickster's Twin at 4th (caster level 7), one cast per result — success: Disbelieve is automatic (no roll) and ends the spell;
    // failure: a Will save (+40) disbelieves; critical failure (Will total DC − 1 + d20, mostly a plain success): only a critical success disbelieves.
    async rank4Batch75(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup("Trickster's Twin");
            await fixture.caster.update({'system.details.level.value': 7});
            const plan = await ctx.api.compile(fixture.spell);
            out.results = [];
            for (const [name, degree] of [['twin success', 'success'], ['twin failure', 'failure'], ['twin critical failure', 'criticalFailure']]) {
                const foe = await ctx.actor(name, {level: 1});
                const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(foe)], castRank: 4, skipConfirmation: true});
                const t = ctx.state(card).targets[0];
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                await ctx.api.saves.finalize(card); await wait(1500);
                const note = foe.itemTypes.effect.find(e => /Trickster's double/.test(e.name));
                const dc = note?.flags?.['pf2e-automatic-resolution']?.runtime?.disbelieve?.dc;
                await foe.update({'system.saves.will.value': degree === 'failure' ? 40 : dc - 1}).catch(() => {});
                const record = ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
                const entry = record?.entries.find(x => x.actorUuid === foe.uuid && x.metadata?.disbelieve);
                const result = entry ? await ctx.api.ongoing.request('disbelieve', {castId: record.castId, uuid: entry.uuid}) : null; await wait(1000);
                const after = ctx.api.ongoing.records().find(r => r.castId === ctx.state(card).castId);
                out.results.push({degree, needs: note?.flags?.['pf2e-automatic-resolution']?.runtime?.disbelieve?.needs ?? null, dc, status: result?.status ?? null, rolled: result?.degree ?? null,
                    ended: result?.ended ?? null, recordStatus: after?.status ?? null, noteLeft: foe.itemTypes.effect.some(e => /Trickster's double/.test(e.name))});
            }
        } catch (error) { out.error = error.stack ?? error.message; }
        const [s, f, c] = out.results ?? [];
        const expectedC = c && (Number(c.rolled) >= 3 ? 'disbelieved' : 'believed');
        assert(!out.error && s?.needs === 'automatic' && s.status === 'disbelieved' && s.rolled === null && s.ended && !s.noteLeft
            && f?.needs === 'success' && f.status === 'disbelieved' && f.rolled >= 2 && f.ended && !f.noteLeft
            && c?.needs === 'criticalSuccess' && Number.isInteger(c.rolled) && c.status === expectedC && c.noteLeft === (expectedC === 'believed'), `Rank 4 batch 75: ${JSON.stringify(out)}`);
        return {batch75: out};
    },
    // Rank 4 batch 74: Stasis at 4th (caster level 7) — success: Stunned 1; failure: the Stasis note for 1 round; critical failure: 3 rounds with the
