            const fixture = await ctx.setup('Compel True Name');
            const plan = await ctx.api.compile(fixture.spell);
            const foes = [];
            for (const name of ['named critical success', 'named success', 'named failure', 'named critical failure']) foes.push(await ctx.actor(name, {level: 1}));
            const tokens = await Promise.all(foes.map(a => ctx.token(a)));
