            const entry = record?.entries.find(e => e.actorUuid === proud.uuid && e.metadata?.triggeredPenalty);
            const penalty = () => proud.itemTypes.effect.filter(e => e.flags?.['pf2e-automatic-resolution']?.triggeredPenalty).map(e => (e.system.rules ?? []).map(r => `${[r.selector].flat()[0]}:${r.value}`).join(','));
            out.results = [];
