    // Rank 4 batch 61: Channel Arrogance at 5th — the GM answers "not a 1-action cast" for a failure: 6d10 mental, Fascinated 1 round, the praise note;
    // "a 1-action cast" for a creature rolling at Will −10: one degree better.
    async rank4Batch61(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Channel Arrogance');
            await fixture.caster.update({'system.details.level.value': 9}); await fixture.spell.update({'system.location.heightenedLevel': 5});
            const plan = await ctx.api.compile(fixture.spell);
            const full = await ctx.actor('arrogance full', {level: 1}), quick = await ctx.actor('arrogance quick', {level: 1});
            for (const x of [full, quick]) await x.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            await quick.update({'system.saves.will.value': -10});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(full), await ctx.token(quick)], castRank: 5, skipConfirmation: true});
            const [a, b] = ctx.state(card).targets;
            await ctx.api.saves.correctTarget(card, a.id, {action: 'adjustment-not-applicable'});
            await ctx.api.saves.correctTarget(card, b.id, {action: 'adjustment-applies'});
            await ctx.api.saves.rollSave(card, a.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, a.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.rollSave(card, b.id, {skipDialog: true});
            await ctx.api.saves.finalize(card); await wait(1500);
            const state = ctx.state(card);
            out.formula = state.damage?.formula ?? null; out.total = state.damage?.total ?? null;
            out.full = {lost: 300 - full.hitPoints.value, fascinated: full.hasCondition('fascinated'), note: full.itemTypes.effect.some(e => /Blurted praise/.test(e.name))};
            out.quick = {rolled: state.targets[1].rolledDegree, degree: state.targets[1].degree, lost: 300 - quick.hitPoints.value};
        } catch (error) { out.error = error.stack ?? error.message; }
        const better = {criticalSuccess: 'criticalSuccess', success: 'criticalSuccess', failure: 'success', criticalFailure: 'failure'};
        const share = {criticalSuccess: 0, success: 0.5, failure: 1, criticalFailure: 2};
        const q = out.quick ?? {};
        assert(!out.error && /^6d10 mental$/.test(out.formula ?? '') && out.full?.lost === out.total && out.full.fascinated && out.full.note
            && q.degree === better[q.rolled] && q.lost === Math.floor(out.total * share[q.degree]),
            `Rank 4 batch 61: ${JSON.stringify(out)}`);
        return {batch61: out};
    },
