            const victim = await ctx.actor('spirits victim'); await victim.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tVictim = await place(victim, 15 * g, 12 * g); await wait(600);
            const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Invoke Spirits', shapes: [{type: 'circle', x: 15.5 * g, y: 12.5 * g, radius: 2 * g}], color: '#666688'}]);
            combat = await Combat.create({scene: canvas.scene.id, active: true});
