            for (const effect of victim.itemTypes.effect.filter(e => e.flags?.['pf2e-automatic-resolution'])) await effect.delete();
            for (const slug of ['frightened', 'fleeing']) await victim.decreaseCondition(slug, {forceRemove: true}).catch(() => {});
            await wait(500);
