            const plan = await ctx.api.compile(fixture.spell);
            const resistant = await ctx.actor('strike resistant', {level: 1}), immune = await ctx.actor('strike immune', {level: 1}), plain = await ctx.actor('strike plain', {level: 1});
            for (const a of [resistant, immune, plain]) await a.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            await resistant.update({'system.attributes.resistances': [{type: 'fire', value: 12}]});
