    // Rank 3 batch 49: Gasping Marsh — a placed sustained area: a creature starting its turn inside saves (Fortitude): a failure takes 4d6 poison and
    // Sickened 1, and is immune for 1 minute (no exposure next round); the notes.
    async rank3Batch49(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        let combat = null, region = null;
        try {
            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const marsh = await ctx.setup('Gasping Marsh');
            const casterToken = canvas.scene.tokens.find(t => t.actorId === marsh.caster.id); await casterToken.update({x: 600, y: 600}, {animate: false});
            const foe = await ctx.actor('marsh foe', {level: 1});
            await foe.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const tFoe = await place(foe, 2050, 1050);
            [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Gasping Marsh', shapes: [{type: 'circle', x: 2100, y: 1100, radius: 2 * canvas.grid.size}], color: '#668844'}]);
            await wait(600);
            const plan = await ctx.api.compile(marsh.spell);
            const started = await ctx.api.ongoing.startLingering(marsh.spell, plan, {castRank: 3, region, dc: 24}); await wait(1200);
            const rec = () => ctx.api.ongoing.records().find(r => r.castId === started.castId);
            out.notes = (rec().declaration.notes ?? []).length;
            const sustain = async () => { if (rec().obligations.some(x => x.kind === 'sustain' && x.status === 'pending')) { await ctx.api.ongoing.request('sustain', {castId: started.castId, revision: rec().revision}); await wait(500); } };
            combat = await Combat.create({scene: canvas.scene.id, active: true});
            await combat.createEmbeddedDocuments('Combatant', [casterToken, tFoe].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
            await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true}); await sustain();
            await combat.nextTurn(); await wait(1000); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(600);
            const o = rec().obligations.find(x => x.kind === 'membership' && x.status === 'pending' && x.actorUuid === foe.uuid);
            out.event = o?.event ?? null;
            await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: o.key, affected: true}); await wait(800);
            const card = game.messages.get(rec().obligations.find(x => x.key === `${o.key}:save`).cardId), target = ctx.state(card).targets[0];
            await ctx.api.saves.rollSave(card, target.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, target.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.finalize(card); await wait(1200);
            out.save = {statistic: ctx.state(card).saveStatistic ?? null, formula: ctx.state(card).damage?.formula ?? null, total: ctx.state(card).damage?.total ?? null,
                lost: 300 - foe.hitPoints.value, sickened: foe.getCondition('sickened')?.value ?? 0, immune: foe.itemTypes.effect.some(e => e.flags?.['pf2e-automatic-resolution']?.spellImmunity)};
            await combat.nextTurn(); await wait(800); await ctx.api.ongoing.reconcile({clockEvent: true}); await sustain();
            await combat.nextTurn(); await wait(1000); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(600);
            out.again = rec().obligations.filter(x => x.kind === 'membership' && x.actorUuid === foe.uuid).length;
            await ctx.api.ongoing.request('end', {castId: started.castId}); await wait(800);
        } catch (error) { out.error = error.stack ?? error.message; }
        if (combat) await combat.delete();
        if (region && canvas.scene.regions.get(region.id)) await region.delete();
        const v = out.save ?? {};
        assert(!out.error && out.notes === 2 && out.event === 'turn-start' && v.statistic === 'fortitude' && /4d6 poison/.test(v.formula) && v.lost === v.total && v.sickened === 1 && v.immune && out.again === 1,
            `Rank 3 batch 49: ${JSON.stringify(out)}`);
        return {batch49: out};
    },
