    // Rank 5 batch 19: Wronged Monk's Wrath, the 2-action variant at 7th — 5d6 force and 5d12 electricity (Reflex): a failure is Deafened 1 round;
    // a critical failure takes double, 2d12 persistent electricity and is Deafened 1 minute.
    async rank5Batch19(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup("Wronged Monk's Wrath");
            await fixture.caster.update({'system.details.level.value': 13}); await fixture.spell.update({'system.location.heightenedLevel': 7});
            const overlayId = Object.entries(fixture.spell._source.system.overlays ?? {}).find(([, o]) => o.system?.time?.value === '2')?.[0];
            const variant = fixture.spell.loadVariant({overlayIds: [overlayId]});
            const plan = await ctx.api.compile(variant);
            out.area = Number(plan.targeting?.area?.value ?? NaN);
            const actors = [await ctx.actor('wrath failure', {level: 1}), await ctx.actor('wrath crit', {level: 1})];
            for (const actor of actors) await actor.update({'system.attributes.hp.value': 400, 'system.attributes.hp.max': 400});
            const {card} = await ctx.api.saves.start(variant, {sourceActor: fixture.caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank: 7, dc: 30, skipConfirmation: true});
            for (const [index, t] of ctx.state(card).targets.entries()) { await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: ['failure', 'criticalFailure'][index]}); }
            await ctx.api.saves.finalize(card); await wait(1500);
            const state = ctx.state(card);
            out.statistic = state.saveStatistic ?? null;
            out.formula = state.damage?.formula ?? null;
            out.total = state.damage?.total ?? null;
            out.lost = actors.map(a => 400 - a.hitPoints.value);
            const deaf = actor => { const e = actor.itemTypes.effect.find(x => (x.flags?.['pf2e-automatic-resolution']?.outcomeEffect?.conditions ?? []).some(c => c.slug === 'deafened'));
                return e ? `${e.system.duration.value} ${e.system.duration.unit}` : (actor.hasCondition('deafened') ? 'condition' : null); };
            out.deafened = actors.map(deaf);
            out.persistent = actors.map(a => a.itemTypes.condition.find(c => c.slug === 'persistent-damage')?.system.persistent?.formula ?? null);
        } catch (error) { out.error = error.stack ?? error.message; }
        assert(!out.error && out.area === 10 && out.statistic === 'reflex' && /5d6/.test(out.formula) && /5d12/.test(out.formula) && out.lost[0] === out.total && out.lost[1] === out.total * 2
            && out.deafened[0] === '1 rounds' && out.deafened[1] === '1 minutes' && !out.persistent[0] && /2d12/.test(out.persistent[1] ?? ''), `Rank 5 batch 19: ${JSON.stringify(out)}`);
        return {batch19: out};
    },
    // Rank 5 batch 18: Unusual Anatomy at 7th — PF2e's Effect on the caster (resistance 15 to precision and critical hits, darkvision); Retaliate
    // deals 3d6 acid to the attacker.
