    // Rank 4 batch 41: Ordained Purpose — three enemies save; the GM picks "worse" for one, "better" for one, neither for one: each final degree is
    // its rolled degree shifted that way; the failing ones get the Drop Prone note; the ally isn't eligible.
    async rank4Batch41(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        const WORSE = {criticalSuccess: 'success', success: 'failure', failure: 'criticalFailure', criticalFailure: 'criticalFailure'};
        const BETTER = {criticalSuccess: 'criticalSuccess', success: 'criticalSuccess', failure: 'success', criticalFailure: 'failure'};
        try {
            const fixture = await ctx.setup('Ordained Purpose');
            await fixture.caster.update({'system.details.alliance': 'party'});
            const plan = await ctx.api.compile(fixture.spell);
            const names = ['purpose worse', 'purpose better', 'purpose neither', 'purpose ally'];
            const actors = await Promise.all(names.map(name => ctx.actor(name, {level: 1})));
            for (const [index, actor] of actors.entries()) await actor.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300, 'system.details.alliance': index === 3 ? 'party' : 'opposition'});
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank: 4, dc: 20, skipConfirmation: true});
            out.eligible = ctx.state(card).targets.map(t => t.eligible !== false);
            out.question = /Does either described creature apply/.test(game.messages.get(card.id).content);
            const choices = ['worse', 'better', null];
            out.rows = [];
            for (const [index, t] of ctx.state(card).targets.entries()) {
                if (t.eligible === false) continue;
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true});
                const now = ctx.state(card).targets.find(x => x.id === t.id);
                const rolled = now.degree;
                await ctx.api.saves.correctTarget(card, t.id, choices[index] ? {action: 'adjustment-choice', degree: choices[index], expectedRevision: now.revision} : {action: 'adjustment-not-applicable', expectedRevision: now.revision});
                const final = ctx.state(card).targets.find(x => x.id === t.id).degree;
                out.rows.push({rolled, final, expected: choices[index] === 'worse' ? WORSE[rolled] : choices[index] === 'better' ? BETTER[rolled] : rolled});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            out.total = ctx.state(card).damage?.total ?? null;
            out.lost = actors.map(a => 300 - a.hitPoints.value);
            out.compelled = actors.map(a => !!a.itemTypes.effect.find(e => /Compelled/.test(e.name)));
        } catch (error) { out.error = error.stack ?? error.message; }
        const mult = {criticalSuccess: 0, success: 0.5, failure: 1, criticalFailure: 2};
        const rowsOk = (out.rows ?? []).length === 3 && out.rows.every((row, index) => row.final === row.expected
            && out.lost[index] === Math.floor((out.total ?? 0) * mult[row.final]) && out.compelled[index] === ['failure', 'criticalFailure'].includes(row.final));
        assert(!out.error && out.question && JSON.stringify(out.eligible) === '[true,true,true,false]' && rowsOk && out.lost[3] === 0, `Rank 4 batch 41: ${JSON.stringify(out)}`);
        return {batch41: out};
    },
    // Rank 4 batch 40: Confront Selves — at cast a failure (4d6 mental, Clumsy 1 until the caster's next turn); a Sustain repeat: a critical success
    // (nothing); at 6th: 6d6.
    async rank4Batch40(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const out = {};
        try {
            const fixture = await ctx.setup('Confront Selves');
            // (A focus spell heightens to half the caster's level: the level sets the cast rank.)
            const foe = await ctx.actor('confront foe', {level: 1});
            await foe.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
            const token = await ctx.token(foe);
            const cast = async (rank, degree) => {
                await fixture.caster.update({'system.details.level.value': rank * 2 - 1});
                for (const effect of foe.itemTypes.effect) await effect.delete();
                const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan: await ctx.api.compile(fixture.spell), targets: [token], castRank: rank, dc: 26, skipConfirmation: true});
                const [t] = ctx.state(card).targets;
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
                const before = foe.hitPoints.value;
                await ctx.api.saves.finalize(card); await wait(1200);
                const state = ctx.state(card);
                const clumsy = foe.itemTypes.effect.find(e => (e.flags?.['pf2e-automatic-resolution']?.outcomeEffect?.conditions ?? []).some(c => c.slug === 'clumsy'));
                return {statistic: state.saveStatistic ?? null, formula: state.damage?.formula ?? null, total: state.damage?.total ?? null, lost: before - foe.hitPoints.value,
                    clumsy: foe.getCondition('clumsy')?.value ?? 0, expiry: clumsy?.system.duration.expiry ?? null, notes: /don't Sustain it again/.test(game.messages.get(card.id).content)};
            };
            out.cast = await cast(4, 'failure');
            out.sustain = await cast(4, 'criticalSuccess');
            out.heightened = await cast(6, 'failure');
        } catch (error) { out.error = error.stack ?? error.message; }
        const c = out.cast ?? {}, s = out.sustain ?? {}, h = out.heightened ?? {};
        assert(!out.error && c.statistic === 'will' && /4d6 mental/.test(c.formula) && c.lost === c.total && c.clumsy === 1 && c.expiry === 'turn-start' && c.notes
            && s.lost === 0 && s.clumsy === 0 && /6d6 mental/.test(h.formula) && h.lost === h.total, `Rank 4 batch 40: ${JSON.stringify(out)}`);
        return {batch40: out};
    },
