            out.undead = {lost: 200 - undead.system.attributes.hp.value, roll: msg?.rolls?.[0]?.formula ?? null, total: msg?.rolls?.[0]?.total ?? null};
            out.livingLost = 200 - living.system.attributes.hp.value;
