            await ctx.api.ongoing.request('sustain', {castId: started.castId, revision: rec().revision}); await wait(1200); await ctx.api.ongoing.reconcile({clockEvent: true}); await wait(800);
            out.second = await resolve(foe2, 'criticalFailure');
