            const m = describe(noteOf(misty.caster, 'Misty Memory'));
            out.misty = {duration: m?.duration ?? null, winds: /Strong winds from a magical source/.test(m?.text ?? '')};
            const winds = await ctx.setup('Wisdom of the Winds');
            await ctx.api.execute(winds.spell, {sourceActor: winds.caster, plan: await ctx.api.compile(winds.spell), castRank: 5, skipConfirmation: true}); await wait(800);
            const w = describe(noteOf(winds.caster, 'Wisdom of the Winds'));
