        assert(!out.error && out.airlift.note && !out.airlift.effect && out.airlift.unwilling && out.airlift.heightened && out.vision.duration === '1 hours' && out.vision.save
            && out.misty.duration === '10 minutes' && out.misty.winds && out.winds.duration === '8 hours' && out.winds.options, `Rank 4 batch 27: ${JSON.stringify(out)}`);
        return {batch27: out};
