            const tAttacker = await ctx.token(attacker);
            const refused = await ctx.api.saves.start(pain.spell, {plan, sourceActor: pain.caster, targets: [tAttacker], castRank: 4, dc: 25, skipConfirmation: true}).then(() => 'started', e => e.message);
            await pain.caster.update({'system.attributes.hp.value': 200, 'system.attributes.hp.max': 200});
            await pain.caster.applyDamage({damage: 21, token: canvas.scene.tokens.find(t => t.actorId === pain.caster.id)}); await wait(800);
            const {card} = await ctx.api.saves.start(pain.spell, {plan, sourceActor: pain.caster, targets: [tAttacker], castRank: 4, dc: 25, skipConfirmation: true});
            const t = ctx.state(card).targets[0];
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: 'failure'});
            await ctx.api.saves.rollDamage?.(card).catch(() => null);
