            await ctx.api.execute(bind.spell, {sourceActor: bind.caster, plan: bplan, castRank: 6, skipConfirmation: true}); await wait(1000);
            const note = game.messages.contents.find(m => !messages.has(m.id) && /Remove the target thrall/.test(m.content));
            out.bind = {kind: bplan.resolution.kind, level: bplan.automation.level, effect: bind.caster.itemTypes.effect.some(e => e.name === 'Spell Effect: Bind Heroic Spirit'),
                fortitude: bind.caster.saves.fortitude.mod - before, note: !!note};
            const bard = await character('Fortissimo bard', 2000), ally = await character('Fortissimo ally', 2100);
            const [fortissimo, anthem] = await learn(bard, ['Fortissimo Composition', 'Courageous Anthem']);
            const fplan = await ctx.api.compile(fortissimo), aplan = await ctx.api.compile(anthem);
            const allyToken = ally.getActiveTokens(true, true)[0];
            const first = await ctx.api.execute(fortissimo, {sourceActor: bard, plan: fplan, targets: [allyToken], degree: 'criticalSuccess', skipDialog: true, skipConfirmation: true}); await wait(700);
            await ctx.api.execute(anthem, {sourceActor: bard, plan: aplan, castRank: 1, skipConfirmation: true}); await wait(2500);
            const boost = ally.itemTypes.effect.find(e => e.name.startsWith('Spell Effect: Fortissimo Composition'));
            out.fortissimo = {kind: fplan.resolution.kind, level: fplan.automation.level, dc: first.dc, willDC: ally.saves.will.dc.value, anthem: ally.itemTypes.effect.some(e => e.name === 'Spell Effect: Courageous Anthem'),
                boost: boost?.flags?.system?.rulesSelections?.fortissimoBonus ?? null, applied: bard.getFlag(NSX, 'spellshapePending')?.applied ?? null};
            for (const e of [...ally.itemTypes.effect, ...bard.itemTypes.effect]) await e.delete().catch(() => null);
