            await canvas.scene.createEmbeddedDocuments('Token', [{...caster.prototypeToken.toObject(), actorId: caster.id, actorLink: true, x: 2000, y: 1000}]);
            const [entry] = await caster.createEmbeddedDocuments('Item', [{name: 'Primal casting', type: 'spellcastingEntry', system: {tradition: {value: 'primal'}, prepared: {value: 'innate'}, spelldc: {dc: 25, value: 15}}}]);
            const pack = game.packs.get('pf2e.spells-srd'), row = (await pack.getIndex()).find(item => item.name === name);
            const source = (await pack.getDocument(row._id)).toObject(); delete source._id; source.system.location = {value: entry.id};
            const [spell] = await caster.createEmbeddedDocuments('Item', [source]);
