            const form = elephant.caster.itemTypes.effect.find(e => e.name === 'Spell Effect: Elephant Form');
            out.elephant = {kind: eplan.resolution.kind, level: eplan.automation.level, effect: !!form, size: elephant.caster.size,
                tempHP: elephant.caster.attributes.hp.temp, trunk: (form?.system.rules ?? []).some(r => r.key === 'Note' && /GrabbingTrunk/.test(r.title))};
            const swarm = await setup('Swarm Form', 11);
