                for (const a of actors) await a.update({'system.attributes.hp.value': 300, 'system.attributes.hp.max': 300});
                const {card} = await ctx.api.saves.start(variant, {sourceActor: whirl.caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank: 5, dc: 25, skipConfirmation: true});
                for (const [i, t] of ctx.state(card).targets.entries()) { await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]}); }
                await ctx.api.saves.finalize(card); await wait(1500);
