            await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(ally)], castRank: 3, skipConfirmation: true}); await wait(1000);
            const effect = ally.itemTypes.effect.find(e => e.name.startsWith("Spell Effect: Sun's Fury"));
