        const out = {};
        const extra = [];
        const overlayFor = (spell, time) => Object.entries(spell._source.system.overlays ?? {}).find(([, o]) => o.system?.time?.value === time)?.[0];
        const save = async (spell, caster, actors, degrees, rank) => {
            const plan = await ctx.api.compile(spell);
            const {card} = await ctx.api.saves.start(spell, {sourceActor: caster, plan, targets: await Promise.all(actors.map(a => ctx.token(a))), castRank: rank, dc: 30, skipConfirmation: true});
            for (const [i, t] of ctx.state(card).targets.entries()) {
                if (t.eligible === false) continue;
                await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: degrees[i]});
            }
            await ctx.api.saves.finalize(card); await wait(1500);
            return {supported: ctx.api.saves.supports(plan), state: ctx.state(card)};
        };
