            let rolled = null;
            if (link) { const formula = /@Damage\[(.+)\]$/.exec(link)[1].replace(/@item\.level/g, String(note.system.level.value)); const DamageRoll = CONFIG.Dice.rolls.find(r => r.name === 'DamageRoll'); rolled = new DamageRoll(formula).formula; }
