            await fixture.caster.update({'system.details.level.value': 9});
            const plan = await ctx.api.compile(fixture.spell);
            const {card} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(actor)], castRank: fixture.spell.rank, dc: 25, skipConfirmation: true});
            const t = ctx.state(card).targets[0];
            out[`${name} eligible`] = t?.eligible ?? null;
            if (t?.eligible === false) return {plan, card, refused: true, reason: t.ineligibleReason ?? t.reason ?? null};
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
            await ctx.api.saves.finalize(card); await wait(1500);
