        for (const actor of extra) { await canvas.scene.deleteEmbeddedDocuments('Token', canvas.scene.tokens.filter(t => t.actorId === actor.id).map(t => t.id)); await actor.delete(); }
        const sb = out.subjugate ?? {};
        assert(!out.error && sb.supported && sb.note && sb.duration === '1 minutes' && sb.minion && sb.highRefused
            && out['Sudden Recollection']?.note && out['Sudden Recollection'].unit === 'unlimited' && out['Rewrite Memory']?.note && out['Rewrite Memory'].unit === 'unlimited', `Rank 3 batch 24: ${JSON.stringify(out)}`);
        return {batch24: out};
