            out.living = {frightened: living.getCondition('frightened')?.value ?? 0, paralyzed: living.hasCondition('paralyzed'), quickened: living.hasCondition('quickened')};
            out.construct = {quickened: construct.hasCondition('quickened'), frightened: construct.hasCondition('frightened')};
