            await fixture.caster.update({'system.attributes.hp.temp': 0}); for (const e of fixture.caster.itemTypes.effect.filter(e => /Drain Life/.test(e.name))) await e.delete(); await wait(500);
            const low = await ctx.actor('drain low'); await low.update({'system.attributes.hp.value': 3});
