            // The ally's ranged attack roll against the target (the triggering attack).
            await ChatMessage.create({content: '<p>PFTEST ranged attack</p>', flags: {pf2e: {context: {type: 'attack-roll', target: {actor: foe.uuid}, outcome: 'success'}}}}); await wait(1500);
            out.afterAttack = {offGuard: foe.hasCondition('off-guard'), ac: foe.armorClass.value === ac};
            const s = await cast(other, 'success');
            out.success = {lost: 500 - other.hitPoints.value, offGuard: other.hasCondition('off-guard'), immunity: other.itemTypes.effect.some(e => /immun/i.test(e.name))};
