            const blizzard = await ctx.setup('Personal Blizzard');
            const strong = await ctx.actor('blizzard strong', {save: 60}), weak = await ctx.actor('blizzard weak', {save: -30}), plain = await ctx.actor('blizzard plain');
            const tStrong = await ctx.token(strong), tWeak = await ctx.token(weak), tPlain = await ctx.token(plain);
            const plan = await ctx.api.compile(blizzard.spell);
