            const ritual = await ctx.setup('Sweetest Solstice');
            const a = await ctx.actor('solstice helper a'), b = await ctx.actor('solstice helper b'), c = await ctx.actor('solstice helper c'), d = await ctx.actor('solstice helper d');
            const plan = await ctx.api.compile(ritual.spell);
            out.level = plan.automation.level;
            try { await ctx.api.execute(ritual.spell, {sourceActor: ritual.caster, plan, skipConfirmation: true, degree: 'success', secondaryCasters: [a, b, c, d].map(x => x.uuid)}); out.refused = null; } catch (error) { out.refused = error.message; }
            const modifiers = async (actor, options) => {
                const before = new Set(game.messages.contents.map(m => m.id));
                await actor.saves.will.roll({dc: {value: 1}, skipDialog: true, extraRollOptions: options}); await wait(500);
                const message = game.messages.contents.find(m => !before.has(m.id) && m.flags?.pf2e?.context?.type === 'saving-throw');
                return (message?.flags.pf2e.modifiers ?? []).filter(m => m.enabled && /solstace/.test(m.slug)).map(m => `${m.slug}:${m.modifier}`).sort();
            };
            const success = await ctx.api.execute(ritual.spell, {sourceActor: ritual.caster, plan, skipConfirmation: true, degree: 'success', secondaryCasters: [a.uuid, b.uuid]}); await wait(1000);
            const effectOf = actor => actor.itemTypes.effect.find(e => e.flags?.[NSX]?.runtime?.resolutionKind === 'ritual-outcome');
            out.success = {casters: success.casters.length, effects: [ritual.caster, a, b, c].map(x => !!effectOf(x)), duration: effectOf(a)?.system.duration,
                fear: await modifiers(a, ['fear']), emotion: await modifiers(a, ['emotion'])};
            for (const x of [ritual.caster, a, b]) await effectOf(x)?.delete();
            const critical = await ctx.api.execute(ritual.spell, {sourceActor: ritual.caster, plan, skipConfirmation: true, degree: 'criticalSuccess', secondaryCasters: [c.uuid]}); await wait(1000);
            out.critical = {effects: [ritual.caster, c].map(x => !!effectOf(x)), duration: effectOf(c)?.system.duration?.value, emotion: await modifiers(c, ['emotion']), fear: await modifiers(c, ['fear']),
                winter: /end of winter/.test(effectOf(c)?.system.description.value ?? '')};
