            out.failure = {applied: failure.applied.length};
            await ctx.api.execute(ritual.spell, {sourceActor: ritual.caster, plan, skipConfirmation: true, degree: 'criticalFailure', secondaryCasters: [d.uuid]}); await wait(1200);
