            const lockEffect = d.itemTypes.effect.find(e => e.flags?.[NSX]?.ritualLock);
            out.criticalFailure = {caster: sick(ritual.caster), helper: atLock, afterReduce: sick(d), lockHours: lockEffect?.system.duration.value};
