            await d.decreaseCondition('sickened'); await wait(500);
            out.criticalFailure.afterLock = afterLock; out.criticalFailure.reducedAfter = sick(d);
            const card = game.messages.contents.filter(m => m.getFlag(NSX, 'kind') === 'ritual-outcome').at(-1);
