            const place = async (actor, x, y) => (await canvas.scene.createEmbeddedDocuments('Token', [{...actor.prototypeToken.toObject(), actorId: actor.id, actorLink: true, x, y}]))[0];
            const walker = await ctx.actor('surge walker', {level: 1}), swimmer = await ctx.actor('surge swimmer', {level: 1, save: -20}), huge = await ctx.actor('surge huge', {level: 1}), later = await ctx.actor('surge later', {level: 1});
            await huge.update({'system.traits.size.value': 'huge'});
