            await ally.createEmbeddedDocuments('Item', [{name: 'Hand Crossbow', type: 'weapon', system: {damage: {dice: 1, die: 'd6', damageType: 'piercing'}, category: 'simple', group: 'crossbow', range: 60, reload: {value: '1'}, usage: {value: 'held-in-one-hand'}, equipped: {carryType: 'held', handsHeld: 1}}}]);
