        await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan: await ctx.api.compile(fixture.spell), targets: [], castRank: 1, skipConfirmation: true}); await wait(1000);
        const record = ctx.api.ongoing.records().find(r => r.name === 'Shields of the Spirit' && r.status === 'active');
        const entry = record?.entries?.find(e => e.metadata?.retaliation);
        const effect = fixture.caster.itemTypes.effect.find(e => e.name.startsWith('Spell Effect: Shields of the Spirit'));
        const raised = fixture.caster.itemTypes.effect.some(e => /Raise a Shield/i.test(e.name));
        const before = foe.hitPoints.value;
        const hit = await ctx.api.ongoing.request('retaliate', {castId: record.castId, uuid: entry.uuid, index: 0, targetUuid: tFoe.uuid}); await wait(800);
        const out = {effect: effect ? `${effect.system.duration.value} ${effect.system.duration.unit} ${effect.system.duration.expiry}` : null, raised,
            trigger: entry?.metadata?.retaliation?.triggers?.[0]?.trigger ?? null, hit: {total: hit?.total, formula: hit?.formula, lost: before - foe.hitPoints.value}};
