        const plan = await ctx.api.compile(fixture.spell);
        const {card: card3} = await ctx.api.saves.start(fixture.spell, {sourceActor: fixture.caster, plan, targets: [await ctx.token(foe)], castRank: 3, dc: 24, skipConfirmation: true});
        const t = ctx.state(card3).targets[0];
