        await ctx.api.saves.finalize(card3); await wait(1000);
        const note3 = notes()[0];
        out.rank3 = {formula: ctx.state(card3).damage?.formula, dazzled: dazzled(foe), heightened: /Heightened \(\+2\) ×1:[^]*increases by 10 feet/.test(note3?.system.description.value ?? '')};
        assert(/^3d4/.test(out.rank3.formula ?? '') && out.rank3.dazzled === '2 rounds' && out.rank3.heightened, `Rainbow's End rank 3: ${JSON.stringify(out.rank3)}`);
        return out;
