        await combat.startCombat(); await wait(600); await ctx.api.ongoing.reconcile({clockEvent: true});
        for (let i = 0; i < 4; i++) { await combat.nextTurn(); await wait(500); await ctx.api.ongoing.reconcile({clockEvent: true}); }
        await wait(600);
