        const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id); await move(casterToken, 8 * g, 3 * g);
        const [near, edge, far, held] = await Promise.all(['garden near', 'garden edge', 'garden far', 'garden held'].map(name => ctx.actor(name)));
        const tNear = await place(near, 9 * g, 3 * g), tEdge = await place(edge, 10 * g, 3 * g), tFar = await place(far, 20 * g, 3 * g), tHeld = await place(held, 8 * g, 4 * g);
        const pack = game.packs.get('pf2e.spell-effects'), entry = (await pack.getIndex()).find(e => e.name === 'Spell Effect: Garden of Healing');
        const doc = await pack.getDocument(entry._id), src = doc.toObject(); src._stats = {...(src._stats ?? {}), compendiumSource: doc.uuid};
        await held.createEmbeddedDocuments('Item', [src]);
