        const h0 = hp();
        const plan = await ctx.api.compile(fixture.spell);
        const cast = await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [], castRank: 2, skipConfirmation: true}); await wait(1200);
        const rec = () => ctx.api.ongoing.records().find(r => r.castId === cast.castInstanceId);
