        const [crit, fail, later] = await Promise.all(['sand crit', 'sand fail', 'sand later'].map(name => ctx.actor(name)));
        const tCrit = await place(crit, 12 * g, 14 * g), tFail = await place(fail, 13 * g, 14 * g), tLater = await place(later, 20 * g, 14 * g);
        await wait(800);
        const [region] = await canvas.scene.createEmbeddedDocuments('Region', [{name: 'PFTEST Scouring Sand area', shapes: [{type: 'circle', x: 13 * g, y: 14.5 * g, radius: 2 * g}], color: '#ccaa55'}]);
        const plan = await ctx.api.compile(fixture.spell);
