        out.controls = entries.filter(e => e.actor === crit.uuid).map(e => e.action).sort();
        const next = entries.find(e => e.actor === crit.uuid && e.action === 'next');
        if (next) { await ctx.api.ongoing.request('action-end', {castId: next.castId, uuid: next.uuid}); await wait(800); }
        out.afterNextAction = conditions(crit);
