        assert(JSON.stringify(out.afterCast) === '{"crit":["blinded"],"fail":["dazzled"]}' && out.card.terrain && out.card.counteract && out.card.immune
            && JSON.stringify(out.controls) === '["interact","next"]' && JSON.stringify(out.afterNextAction) === '["dazzled"]'
            && JSON.stringify(out.turnEnd) === '["turn-end"]' && JSON.stringify(out.later) === '["dazzled"]', `Scouring Sand: ${JSON.stringify(out)}`);
