        const out = {lost: first.lost, drained, conditions: victim.itemTypes.condition.map(c => `${c.slug}${c.value ?? ''}`), healed: healed.amount, allyGained: ally.hitPoints.value - allyBefore,
            lock: ally.itemTypes.effect.filter(e => /healed \(not again/.test(e.name)).map(e => `${e.system.duration.value} ${e.system.duration.unit}`),
            reminder: /is destroyed: remove its token/.test(game.messages.get(first.card.id).content)};
