            if (t.confirmation?.status === 'pending') { await ctx.api.saves.correctTarget(card, t.id, {action: 'affected', expectedRevision: t.revision}); t = ctx.state(card).targets[index]; }
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true});
