        const cast = delta(mods());
        const card = game.messages.contents.filter(m => m.flags?.['pf2e-automatic-resolution']?.kind === 'offer-effect').at(-1);
        const button = document.querySelector(`[data-message-id="${card.id}"] button[data-runtime-action="suppress"]`);
        button?.click(); await wait(1500);
        const suppressed = delta(mods());
        const marker = caster.itemTypes.effect.find(effect => /price suppressed/.test(effect.name));
