        const wait = ms => new Promise(r => setTimeout(r, ms));
        const fixture = await ctx.setup('Pyroclastic Truth');
        const caster = fixture.caster;
        const [burned, spared] = await Promise.all(['pyro burned', 'pyro spared'].map(name => ctx.actor(name, {level: 1})));
        const tokens = await Promise.all([burned, spared].map(ctx.token));
