        const NSP = 'pf2e-automatic-resolution';
        const move = (token, x, y) => token.update({x, y}, {teleport: true, animate: false});
        const g = canvas.grid.size;
        const fixture = await ctx.setup('Manifest Will');
        const caster = fixture.caster;
        const casterToken = canvas.scene.tokens.find(t => t.actorId === caster.id); await move(casterToken, 2200, 1100);
        const [ally, enemy, far] = await Promise.all(['will ally', 'will enemy', 'will far'].map(name => ctx.actor(name, {level: 1})));
