        const plan = await ctx.api.compile(fixture.spell);
        const cast = rank => ctx.api.execute(fixture.spell, {sourceActor: caster, plan, targets: [], castRank: rank, skipConfirmation: true});
        const climb = async dc => { await caster.skills.athletics.roll({dc: {value: dc}, extraRollOptions: ['action:climb'], skipDialog: true}); await wait(1200);
            return game.messages.contents.filter(m => m.flags?.pf2e?.context?.type === 'skill-check' && m.speaker?.actor === caster.id).at(-1); };
        const falls = () => game.messages.contents.filter(m => m.flags?.['pf2e-automatic-resolution']?.kind === 'climb-aid-fall');
        const first = await cast(1); await wait(800);
