        assert(!out.error && i.name === 'Musical Instrument (Handheld)' && i.held === 'held' && i.replaced.items.length === 1 && /Virtuoso/.test(i.replaced.items[0]) && i.replaced.effects === 1 && i.removed
            && arms.offered > 0 && /\(Arms of Nature\)/.test(arms.name) && arms.potency === 1 && arms.striking === 1 && arms.held === 'held' && arms.strike && arms.heavyRefused && arms.removed
            && m.item === 'Buckler' && m.after === Math.min(m.max, m.before + 5) && m.brokenBefore && !m.brokenAfter && m.repaired && m.steelRank1Refused && m.steelRank2[1] === m.steelRank2[0] + 10, `Items: ${JSON.stringify(out)}`);
