            out.cage.replaced = {walls: mine().length, oldGone: !canvas.scene.lights.get(c1.lightId) && !canvas.scene.regions.get(rc.id), effects: hc.caster.itemTypes.effect.filter(e => e.flags?.[NSP]?.sceneWalls).length};
