    // Cantrip / rank 1 batch 56: Dirge of Doom — enemies targeted in the emanation held at Frightened 1 (an ally refused); the floor
    // survives the end of the enemy's turn.
    async cr1Batch56(ctx) {
        const wait = ms => new Promise(r => setTimeout(r, ms));
        const fixture = await ctx.setup('Dirge of Doom');
        const foe = await ctx.actor('dirge foe'), friend = await ctx.actor('dirge friend');
        await friend.update({'system.details.alliance': 'party'});
        const [tFoe, tFriend] = await Promise.all([foe, friend].map(ctx.token));
        const casterToken = canvas.scene.tokens.find(t => t.actorId === fixture.caster.id);
        const plan = await ctx.api.compile(fixture.spell);
        let refused = null;
        try { await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [tFoe, tFriend], castRank: 1, skipConfirmation: true}); } catch (error) { refused = error.message; }
        const combat = await Combat.create({scene: canvas.scene.id, active: true});
        await combat.createEmbeddedDocuments('Combatant', [casterToken, tFoe].map((t, i) => ({tokenId: t.id, sceneId: canvas.scene.id, actorId: t.actorId, initiative: 30 - i * 10})));
        await combat.startCombat(); await wait(600);
        await ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [tFoe], castRank: 1, skipConfirmation: true}); await wait(1000);
        const atCast = foe.getCondition?.('frightened')?.value ?? 0;
        const effect = foe.itemTypes.effect.find(e => e.name.startsWith('Dirge of Doom: Frightened'));
        const effectDuration = effect ? `${effect.system.duration.value} ${effect.system.duration.unit}` : null;
        // PF2e reduces Frightened (as at the end of the creature's turn): the floor holds it at 1 while the spell lasts.
        try { await foe.decreaseCondition('frightened'); } catch (_) {}
        await wait(600);
        const afterDecrease = foe.getCondition?.('frightened')?.value ?? 0;
        // The round ends (the caster's next turn): the spell and its hold end.
        await combat.nextTurn(); await wait(500); await combat.nextTurn(); await wait(1000);
        const afterSpell = foe.itemTypes.effect.some(e => e.name.startsWith('Dirge of Doom: Frightened'));
        const out = {refused, atCast, afterDecrease, effect: effectDuration, afterSpell, friendFrightened: friend.hasCondition('frightened')};
        await combat.delete();
        assert(/only the enemies in the area/.test(refused ?? '') && !out.friendFrightened && out.atCast === 1 && out.afterDecrease === 1 && out.effect === '1 rounds' && !out.afterSpell,
            `Dirge of Doom: enemies only, Frightened 1 held: ${JSON.stringify(out)}`);
        return {dirgeOfDoom: out};
    },
