        const obligation = rec().obligations.find(o => o.kind === 'membership' && o.actorUuid === foe.uuid && o.status === 'pending');
        await ctx.api.ongoing.request('review-targets', {castId: started.castId, revision: rec().revision, key: obligation.key, affected: true}); await wait(800);
        const save = rec().obligations.find(x => x.key === `${obligation.key}:save`);
        const card = game.messages.get(save.cardId); let t = ctx.state(card).targets[0];
        await ctx.api.saves.rollSave(card, t.id, {skipDialog: true}); t = ctx.state(card).targets[0];
        await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree: 'failure'});
        await ctx.api.saves.finalize(card); await wait(1200);
        const note = foe.itemTypes.effect.find(e => e.name === "Nymph's Grace: While confused");
        const out = {atCast, obligation: !!obligation, confused: foe.hasCondition('confused'), note: note ? `${note.system.duration.value} ${note.system.duration.unit}` : null};
        await ctx.api.ongoing.request('end', {castId: started.castId}); await wait(500);
        await combat.delete();
        assert(out.atCast === 0 && out.obligation && out.confused && out.note === '1 rounds', `Nymph's Grace: turn-start exposure, Confused and the note: ${JSON.stringify(out)}`);
        return {nymphsGrace: out};
