        const eligible = ctx.state(card).targets.map(t => t.eligible !== false);
        for (const [index, degree] of ['success', 'failure', 'criticalFailure'].entries()) {
            const t = ctx.state(card).targets[index];
            await ctx.api.saves.rollSave(card, t.id, {skipDialog: true});
            await ctx.api.saves.correctTarget(card, t.id, {action: 'degree', degree});
        }
