        await fixture.caster.createEmbeddedDocuments('Item', [await weaponSource('Club'), await weaponSource('Longsword')]);
        await wait(500);
        const club = fixture.caster.itemTypes.weapon.find(w => w.name === 'Club'), sword = fixture.caster.itemTypes.weapon.find(w => w.name === 'Longsword');
        const plan = await ctx.api.compile(fixture.spell);
        const messagesBefore = game.messages.contents.length;
        const running = ctx.api.execute(fixture.spell, {sourceActor: fixture.caster, plan, targets: [], castRank: 1, skipConfirmation: true});
        let offered = null;
        for (let i = 0; i < 30; i++) {
            const app = [...foundry.applications.instances.values()].find(x => x.constructor.name === 'PickAThingPrompt');
            const button = app && [...app.element.querySelectorAll('button')].find(b => b.textContent.trim() === 'Club');
            if (button) { offered = [...app.element.querySelectorAll('button')].map(b => b.textContent.trim()).filter(Boolean); button.click(); break; }
            await wait(150);
        }
        await running; await wait(1000);
