        const pack = game.packs.get('pf2e.equipment-srd'), index = await pack.getIndex();
        const weaponSource = async name => { const source = (await pack.getDocument(index.find(e => e.name === name)._id)).toObject(); delete source._id; source.system.equipped = {carryType: 'held', handsHeld: 1}; return source; };
        await fixture.caster.createEmbeddedDocuments('Item', [await weaponSource('Club'), await weaponSource('Longsword')]);
        await wait(500);
