        await combat.nextTurn(); await wait(500);
        await click(); const foeTurn = cards().length; // not on another creature's turn
        await combat.nextTurn(); await wait(500); // round 2, the caster's turn
        await click(); labels.push(button()?.textContent?.trim());
        const s2 = await resolveCard(cards().at(-1), 'criticalSuccess');
        await combat.nextTurn(); await wait(300); await combat.nextTurn(); await wait(500); // round 3
        await click(); await ui.chat.updateMessage?.(message); await wait(800);
        const s3 = await resolveCard(cards().at(-1), 'failure');
